 1, this.ROUNDS.length - 1); var round = this.ROUNDS[idx]; var briefEl = document.getElementById('briefingText'); if (briefEl) { briefEl.innerHTML = window.mySimulation.t(round.description_key); } var panel = document.getElementById('decisionPanel'); if (!panel) return; var html = ''; for (var i = 0; i < round.inputs.length; i++) { var inp = round.inputs[i]; html += '<div class="coalicion-decision-group">'; html += '<label for="' + inp.id + '" data-i18n="' + inp.label_key + '">' + window.mySimulation.t(inp.label_key) + '</label>'; if (inp.type === 'number') { html += '<input type="number" id="' + inp.id + '" min="' + inp.min + '" max="' + inp.max + '" step="' + inp.step + '" value="' + inp.default + '">'; } else if (inp.type === 'select') { html += '<select id="' + inp.id + '">'; for (var j = 0; j < inp.options.length; j++) { var opt = inp.options[j]; var selected = opt == inp.default ? ' selected' : ''; html += '<option value="' + opt + '"' + selected + '>' + opt + '</option>'; } html += '</select>'; } html += '<div class="coalicion-hint">' + window.mySimulation.t(inp.hint_key) + '</div>'; html += '</div>'; } panel.innerHTML = html; } getTranslations() { return { en: { title: `La Coalición — Sierra del Agua Wind Farm`, subtitle: `Multi-party negotiation: stakeholder mapping, coalitions and blocking minorities`, round_label: `Round`, period_of: `of`, project_label: `Project`, investment_label: `Total Investment`, deadline_label: `Deadline`, irr_label: `RA IRR`, dscr_label: `DSCR`, sharing_label: `Total Revenue Sharing`, score_label: `Score`, briefing_heading: `Round Briefing`, decisions_heading: `Your Decisions`, submit_btn: `Submit Decisions`, undo_btn: `Undo Last Round`, validation_range: `Value must be between`, r1_title: `Stakeholder Mapping and Blocking Power`, r1_briefing: `<strong>Round 1 — Stakeholder Mapping and Blocking Power</strong><br><br>The Sierra del Agua Wind Farm (280 MW, Extremadura) requires agreement among four parties: the Regional Government (GREx), Renovables Atlantico (RA, the developer), Banco Iberico de Inversiones (BII, project finance), and the Local Communities (CL, 3 municipalities with 11,480 inhabitants).<br><br>The project requires an investment of €340M (30% equity from RA, 70% debt from BII). Estimated revenue: €80M/year. The deadline for financial close is March 15, 2026 — each month of delay costs €840K.<br><br><strong>Your task:</strong> Rate the blocking power (ability to stop the deal) and BATNA strength (quality of the alternative if no deal) for each party on a 1-5 scale. Consider: who has formal veto power? Who has informal blocking ability? Whose alternative is strongest?`, r1_grex_power: `GREx Blocking Power (1-5)`, r1_ra_power: `RA Blocking Power (1-5)`, r1_bii_power: `BII Blocking Power (1-5)`, r1_cl_power: `CL Blocking Power (1-5)`, r1_grex_batna: `GREx BATNA Strength (1-5)`, r1_ra_batna: `RA BATNA Strength (1-5)`, r1_bii_batna: `BII BATNA Strength (1-5)`, r1_cl_batna: `CL BATNA Strength (1-5)`, r1_power_hint: `1 = no blocking power, 5 = absolute veto`, r1_batna_hint: `1 = very weak alternative, 5 = strong alternative (status quo is fine)`, r1_feedback_title: `Round 1 Results — Power Analysis`, r1_power_score: `Power Mapping Score`, r1_batna_score: `BATNA Analysis Score`, r1_feedback_detail: `Key insight: ALL four parties are necessary. No coalition of 3 can close the deal without the 4th. The CL (small municipalities) have blocking power equal to GREx through administrative litigation — despite their small size.`, r1_correct_power: `Correct Power`, r1_your_power: `Your Rating`, r1_correct_batna: `Correct BATNA`, r1_your_batna: `Your Rating`, r2_title: `Revenue Sharing Structure`, r2_briefing: `<strong>Round 2 — Design the Revenue Sharing Structure</strong><br><br><strong>Financial model:</strong> Gross revenue €80M/year | O&M costs €12M/year | Debt service €22.4M/year | EBITDA pre-sharing €68M/year | DSCR pre-sharing 3.04x<br><br><strong>The conflict:</strong> CL demand 4% revenue sharing (€3.2M/year). RA offers 2.5% (€2M/year). The gap is €1.2M/year — NPV over 25 years at 5%: €16.8M.<br><br>GREx requires a 1.5% concession fee. The CL also want a green municipal tariff (15% discount on electricity for 3 municipalities = ~€153K/year).<br><br><strong>RA red line:</strong> IRR cannot fall below 10%. Total revenue sharing cannot exceed ~5%.<br><strong>BII red line:</strong> DSCR must stay above 1.4x.<br><br><strong>Your task:</strong> Design the revenue sharing that balances all parties. Consider using contingent sharing (additional % only when market price exceeds €0.09/kWh) as an integrative mechanism.`, r2_cl_sharing: `CL Revenue Sharing (%)`, r2_grex_canon: `GREx Concession Fee (%)`, r2_green_tariff: `Green Municipal Tariff Discount (%)`, r2_contingent: `Contingent Sharing — additional % if price > €0.09/kWh`, r2_cl_sharing_hint: `CL demand 4%, RA offers 2.5%. Optimal zone: 3.0-3.5%`, r2_grex_canon_hint: `GREx asks for 1.5% of gross revenue`, r2_green_tariff_hint: `Electricity discount for 3 municipalities. 0-20%`, r2_contingent_hint: `Additional sharing only in high-price years. Aligns interests.`, r2_feedback_title: `Round 2 Results — Revenue Sharing Impact`, r2_total_sharing: `Total Revenue Sharing`, r2_irr_warning: `DANGER: IRR has fallen below the 10% minimum required by RA. The deal is at risk.`, r2_sharing_warning: `Warning: Total sharing is high. RA has limited margin for error.`, r3_title: `Subsidy Regime Solution`, r3_briefing: `<strong>Round 3 — Resolve the Subsidy Regime Conflict</strong><br><br><strong>The problem:</strong> BII requires 15 years of legal certainty on the subsidy regime. The Spanish Energy Law allows up to 12 years with possible 4-year extension. GREx can only legally commit to 10 years with certainty.<br><br><strong>Option A — Legal reinterpretation:</strong> RA lawyers (Garrigues) argue the post-2021 reform allows 15-20 years for projects >200 MW. If the Ministry issues an interpretation note, BII gets the certainty. Cost: €180K in legal fees. Probability: 65%.<br><br><strong>Option B — Political guarantee:</strong> GREx signs a protocol of intent to support regime extension. No legal value but moderate credit risk mitigation for BII.<br><br><strong>Option C — Two-tranche debt structure:</strong> Senior tranche (12 years, 4.8%) + Mezzanine tranche (15 years, 7.2%). Higher blended rate but solves the legal gap.<br><br><strong>Option A+C (recommended):</strong> Pursue the Ministry note while structuring two tranches. If the note arrives, mezzanine converts to senior rate.<br><br>Also consider: offering GREx additional concession fee to actively support Option A (the delay cost of €840K/month makes this rational for RA).`, r3_strategy: `Subsidy Strategy`, r3_senior: `Senior Tranche Amount (€M)`, r3_extra_canon: `Additional GREx Canon for Active Support (%)`, r3_strategy_hint: `A = Legal reinterpretation, B = Political guarantee, C = Two-tranche, AC = Combined A+C`, r3_senior_hint: `Total debt is €238M. Split between senior (12yr, 4.8%) and mezzanine (15yr, 7.2%)`, r3_extra_canon_hint: `Extra % to incentivize GREx support for the Ministry note`, r3_feedback_title: `Round 3 Results — Subsidy Architecture`, r3_chosen_strategy: `Chosen Strategy`, r3_blended_rate: `Blended Interest Rate`, r3_irr_danger: `DANGER: IRR has fallen below the 10% minimum. The deal structure is not viable.`, r3_opt_A: `Option A — Legal Reinterpretation Only`, r3_opt_B: `Option B — Political Guarantee Only`, r3_opt_C: `Option C — Two-Tranche Structure Only`, r3_opt_AC: `Option A+C — Combined (Recommended)`, r4_title: `Final Package and Coalition Close`, r4_briefing: `<strong>Round 4 — Design the Final Package</strong><br><br>Now integrate all previous decisions into a final agreement that closes with all four parties.<br><br>Remaining items to negotiate:<br>- <strong>Local employment:</strong> CL demand 80% of 280 construction jobs for local residents. RA initially offered no commitment. A reasonable range is 60-80%.<br>- <strong>Restoration fund:</strong> CL want a guarantee deposit for land restoration after year 25. Proposed: €3M in escrow at construction start.<br>- <strong>Community development fund:</strong> Annual contribution to local infrastructure. CL request €500K/year (administered by a municipal consortium).<br><br>Each additional commitment has a small impact on the project IRR. Balance generosity with financial viability.<br><br><strong>Success criteria:</strong> All four parties must have satisfaction above 50%, IRR must remain above 10%, and DSCR must stay above 1.4x.`, r4_employment: `Local Employment Commitment (% of 280 jobs)`, r4_restoration: `Land Restoration Fund (€M)`, r4_community_fund: `Annual Community Fund (€K/year)`, r4_employment_hint: `CL demand 80%, RA preference is lower. 60-80% is the negotiation zone.`, r4_restoration_hint: `Escrow deposit for land restoration at year 25. CL want €3M.`, r4_community_fund_hint: `Annual fund for local infrastructure. CL request €500K/year.`, r4_feedback_title: `Round 4 Results — Coalition Outcome`, r4_deal_closed: `DEAL CLOSED — All four parties signed on March 12, 2026!`, r4_deal_failed: `DEAL FAILED — One or more parties rejected the final package.`, col_party: `Party`, col_score: `Score`, col_irr: `IRR (%)`, col_sharing: `Rev. Sharing`, col_deal: `Deal`, hint_r1: `Remember: small actors can have enormous blocking power. The CL can file administrative appeals that delay the project 3-4 years.`, hint_r2_irr: `The IRR is dangerously close to the 10% minimum. Consider reducing the revenue sharing or using contingent mechanisms.`, hint_r2_cl: `The CL may reject less than 3%. Their blocking cost (litigation) is €30.2M — more expensive than conceding the revenue sharing.`, hint_r3: `The combined A+C strategy gives the best outcome: pursue the Ministry note while structuring two tranches as insurance.`, hint_r4: `Check each party satisfaction. If any is below 50%, the deal fails. Adjust your commitments to balance all four.` }, es: { title: `La Coalición — Parque Eólico Sierra del Agua`, subtitle: `Negociación multi-parte: stakeholder mapping, coaliciones y minorías de bloqueo`, round_label: `Ronda`, period_of: `de`, project_label: `Proyecto`, investment_label: `Inversión Total`, deadline_label: `Fecha Límite`, irr_label: `IRR de RA`, dscr_label: `DSCR`, sharing_label: `Revenue Sharing Total`, score_label: `Puntuación`, briefing_heading: `Briefing de Ronda`, decisions_heading: `Tus Decisiones`, submit_btn: `Enviar Decisiones`, undo_btn: `Deshacer Última Ronda`, validation_range: `El valor debe estar entre`, r1_title: `Mapeo de Partes y Poder de Bloqueo`, r1_briefing: `<strong>Ronda 1 — Mapeo de Partes y Poder de Bloqueo</strong><br><br>El Parque Eólico Sierra del Agua (280 MW, Extremadura) requiere acuerdo entre cuatro partes: el Gobierno Regional (GREx), Renovables Atlántico (RA, el promotor), Banco Ibérico de Inversiones (BII, project finance) y las Comunidades Locales (CL, 3 municipios con 11.480 habitantes).<br><br>El proyecto requiere una inversión de €340M (30% equity de RA, 70% deuda de BII). Ingresos estimados: €80M/año. La fecha límite para el cierre financiero es el 15 de marzo de 2026 — cada mes de retraso cuesta €840K.<br><br><strong>Tu tarea:</strong> Valora el poder de bloqueo (capacidad de frenar el deal) y la fortaleza del BATNA (calidad de la alternativa sin acuerdo) de cada parte en escala 1-5. Considera: ¿quién tiene poder de veto formal? ¿Quién tiene capacidad de bloqueo informal? ¿La alternativa de quién es más fuerte?`, r1_grex_power: `Poder de Bloqueo GREx (1-5)`, r1_ra_power: `Poder de Bloqueo RA (1-5)`, r1_bii_power: `Poder de Bloqueo BII (1-5)`, r1_cl_power: `Poder de Bloqueo CL (1-5)`, r1_grex_batna: `Fortaleza BATNA GREx (1-5)`, r1_ra_batna: `Fortaleza BATNA RA (1-5)`, r1_bii_batna: `Fortaleza BATNA BII (1-5)`, r1_cl_batna: `Fortaleza BATNA CL (1-5)`, r1_power_hint: `1 = sin poder de bloqueo, 5 = veto absoluto`, r1_batna_hint: `1 = alternativa muy débil, 5 = alternativa fuerte (el statu quo es aceptable)`, r1_feedback_title: `Resultados Ronda 1 — Análisis de Poder`, r1_power_score: `Puntuación Mapeo de Poder`, r1_batna_score: `Puntuación Análisis BATNA`, r1_feedback_detail: `Insight clave: las CUATRO partes son necesarias. Ninguna coalición de 3 puede cerrar el deal sin la 4a. Las CL (municipios pequeños) tienen poder de bloqueo igual al de GREx mediante recursos contencioso-administrativos — a pesar de su tamaño reducido.`, r1_correct_power: `Poder Correcto`, r1_your_power: `Tu Valoración`, r1_correct_batna: `BATNA Correcto`, r1_your_batna: `Tu Valoración`, r2_title: `Estructura de Revenue Sharing`, r2_briefing: `<strong>Ronda 2 — Diseña la Estructura de Revenue Sharing</strong><br><br><strong>Modelo financiero:</strong> Ingresos brutos €80M/año | Costes O&M €12M/año | Servicio de deuda €22.4M/año | EBITDA pre-sharing €68M/año | DSCR pre-sharing 3.04×<br><br><strong>El conflicto:</strong> Las CL exigen el 4% de revenue sharing (€3.2M/año). RA ofrece el 2.5% (€2M/año). La diferencia es €1.2M/año — VAN a 25 años al 5%: €16.8M.<br><br>GREx requiere un canon de concesión del 1.5%. Las CL también piden una tarifa verde municipal (15% de descuento en electricidad para 3 municipios = ~€153K/año).<br><br><strong>Línea roja de RA:</strong> El IRR no puede caer por debajo del 10%. El revenue sharing total no puede superar ~5%.<br><strong>Línea roja de BII:</strong> El DSCR debe mantenerse por encima de 1.4×.<br><br><strong>Tu tarea:</strong> Diseña el revenue sharing que equilibre a todas las partes. Considera usar sharing contingente (% adicional solo cuando el precio de mercado supere €0.09/kWh) como mecanismo integrador.`, r2_cl_sharing: `Revenue Sharing CL (%)`, r2_grex_canon: `Canon de Concesión GREx (%)`, r2_green_tariff: `Descuento Tarifa Verde Municipal (%)`, r2_contingent: `Sharing Contingente — % adicional si precio > €0.09/kWh`, r2_cl_sharing_hint: `CL piden 4%, RA ofrece 2.5%. Zona óptima: 3.0-3.5%`, r2_grex_canon_hint: `GREx pide el 1.5% de los ingresos brutos`, r2_green_tariff_hint: `Descuento en electricidad para los 3 municipios. 0-20%`, r2_contingent_hint: `Sharing adicional solo en años de precio alto. Alinea los intereses.`, r2_feedback_title: `Resultados Ronda 2 — Impacto del Revenue Sharing`, r2_total_sharing: `Revenue Sharing Total`, r2_irr_warning: `PELIGRO: El IRR ha caído por debajo del mínimo del 10% requerido por RA. El deal está en riesgo.`, r2_sharing_warning: `Advertencia: El sharing total es alto. RA tiene poco margen de error.`, r3_title: `Solución del Régimen de Subvención`, r3_briefing: `<strong>Ronda 3 — Resolver el Conflicto del Régimen de Subvención</strong><br><br><strong>El problema:</strong> BII requiere 15 años de certeza legal sobre el régimen de subvención. La Ley de Energía española permite hasta 12 años con posible extensión de 4 años. GREx solo puede comprometer legalmente 10 años con certeza.<br><br><strong>Opción A — Reinterpretación legal:</strong> Los abogados de RA (Garrigues) argumentan que la reforma post-2021 permite 15-20 años para proyectos >200 MW. Si el Ministerio emite una nota de interpretación, BII obtiene la certeza. Coste: €180K en honorarios. Probabilidad: 65%.<br><br><strong>Opción B — Garantía política:</strong> GREx firma un protocolo de intenciones para apoyar la extensión del régimen. Sin valor jurídico pero mitigante para el modelo de riesgo de BII.<br><br><strong>Opción C — Estructura de deuda two-tranche:</strong> Tramo senior (12 años, 4.8%) + Tramo mezzanine (15 años, 7.2%). Mayor tipo combinado pero resuelve la brecha legal.<br><br><strong>Opción A+C (recomendada):</strong> Gestionar la nota del Ministerio mientras se estructura en dos tramos. Si llega la nota, el mezzanine se convierte a tipo senior.<br><br>Considera también: ofrecer a GREx un canon adicional para que apoye activamente la Opción A (el coste de retraso de €840K/mes hace esto racional para RA).`, r3_strategy: `Estrategia de Subvención`, r3_senior: `Importe Tramo Senior (€M)`, r3_extra_canon: `Canon Adicional GREx por Apoyo Activo (%)`, r3_strategy_hint: `A = Reinterpretación legal, B = Garantía política, C = Two-tranche, AC = Combinada A+C`, r3_senior_hint: `La deuda total es €238M. Se divide entre senior (12 años, 4.8%) y mezzanine (15 años, 7.2%)`, r3_extra_canon_hint: `% extra para incentivar el apoyo activo de GREx a la nota del Ministerio`, r3_feedback_title: `Resultados Ronda 3 — Arquitectura de Subvención`, r3_chosen_strategy: `Estrategia Elegida`, r3_blended_rate: `Tipo de Interés Combinado`, r3_irr_danger: `PELIGRO: El IRR ha caído por debajo del mínimo del 10%. La estructura no es viable.`, r3_opt_A: `Opción A — Solo Reinterpretación Legal`, r3_opt_B: `Opción B — Solo Garantía Política`, r3_opt_C: `Opción C — Solo Estructura Two-Tranche`, r3_opt_AC: `Opción A+C — Combinada (Recomendada)`, r4_title: `Paquete Final y Cierre de Coalición`, r4_briefing: `<strong>Ronda 4 — Diseña el Paquete Final</strong><br><br>Integra todas las decisiones anteriores en un acuerdo final que cierre con las cuatro partes.<br><br>Puntos pendientes de negociación:<br>- <strong>Empleo local:</strong> Las CL piden el 80% de los 280 empleos de construcción para residentes locales. RA inicialmente no se comprometió. Un rango razonable es 60-80%.<br>- <strong>Fondo de restauración:</strong> Las CL quieren un depósito de garantía para la restauración del terreno tras el año 25. Propuesta: €3M en cuenta de garantía al inicio de las obras.<br>- <strong>Fondo de desarrollo comunitario:</strong> Contribución anual a infraestructura local. Las CL piden €500K/año (administrado por un consorcio mancomunado).<br><br>Cada compromiso adicional tiene un pequeño impacto en el IRR del proyecto. Equilibra generosidad con viabilidad financiera.<br><br><strong>Criterio de éxito:</strong> Las cuatro partes deben tener satisfacción superior al 50%, el IRR debe mantenerse por encima del 10%, y el DSCR por encima de 1.4×.`, r4_employment: `Compromiso de Empleo Local (% de 280 empleos)`, r4_restoration: `Fondo de Restauración del Terreno (€M)`, r4_community_fund: `Fondo de Desarrollo Comunitario Anual (€K/año)`, r4_employment_hint: `Las CL piden el 80%, RA prefiere menos. Zona de negociación: 60-80%.`, r4_restoration_hint: `Depósito en cuenta de garantía para restaurar el terreno al año 25. Las CL piden €3M.`, r4_community_fund_hint: `Fondo anual para infraestructura local. Las CL piden €500K/año.`, r4_feedback_title: `Resultados Ronda 4 — Resultado de la Coalición`, r4_deal_closed: `DEAL CERRADO — Las cuatro partes firmaron el 12 de marzo de 2026!`, r4_deal_failed: `DEAL FALLIDO — Una o más partes rechazaron el paquete final.`, col_party: `Parte`, col_score: `Puntuación`, col_irr: `IRR (%)`, col_sharing: `Rev. Sharing`, col_deal: `Deal`, hint_r1: `Recuerda: actores pequeños pueden tener un poder de bloqueo enorme. Las CL pueden interponer recursos contencioso-administrativos que retrasen el proyecto 3-4 años.`, hint_r2_irr: `El IRR está peligrosamente cerca del mínimo del 10%. Considera reducir el revenue sharing o usar mecanismos contingentes.`, hint_r2_cl: `Las CL pueden rechazar menos del 3%. Su coste de bloqueo (litigios) es €30.2M — más caro que conceder el revenue sharing.`, hint_r3: `La estrategia combinada A+C da el mejor resultado: gestiona la nota del Ministerio mientras estructura dos tramos como seguro.`, hint_r4: `Revisa la satisfacción de cada parte. Si alguna está por debajo del 50%, el deal fracasa. Ajusta tus compromisos para equilibrar las cuatro.` } }; } } document.addEventListener('DOMContentLoaded', function() { window.mySimulation = new USF.SimulationFramework(); window.mySimulation.initialize(new CoalicionAdapter(), { simulationType: 'coalicion_negotiation', maxPeriods: 4, autoSaveInterval: 30000 }); }); })();
